-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/zones/Inner_Horutoto_Ruins/npcs/_5ca.lua"]={["Path"]="scripts/zones/Inner_Horutoto_Ruins/npcs/_5ca.lua",["SHA256"]="787863e048a8981dda7a6f66404a3a6e3ec1da04ddc41404acf79005b17c2ba5",["Text"]="-----------------------------------\n-- Area: Inner Horutoto Ruins\n--  NPC: Mahogany Door\n-- Involved In Quest: Making Headlines\n-- Involved in Mission 2-1\n-- !pos -11 0 20 192\n-----------------------------------\nlocal ID = zones[xi.zone.INNER_HORUTOTO_RUINS]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local makingHeadlines = player:getQuestStatus(xi.questLog.WINDURST, xi.quest.id.windurst.MAKING_HEADLINES)\n\n    -- bitmask of progress: 0 = Kyume-Romeh, 1 = Yuyuju, 2 = Hiwom-Gomoi, 3 = Umumu, 4 = Mahogany Door\n    local prog = player:getCharVar('QuestMakingHeadlines_var')\n\n    if\n        makingHeadlines == xi.questStatus.QUEST_ACCEPTED and\n        utils.mask.isFull(prog, 4) and\n        not utils.mask.getBit(prog, 4)\n    then\n        player:messageSpecial(ID.text.CAT_BURGLARS_HIDEOUT, 1, xi.keyItem.WINDURST_WOODS_SCOOP) -- Confirm Story\n        player:setCharVar('QuestMakingHeadlines_var', utils.mask.setBit(prog, 4, true))\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Bubupp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Bubupp.lua",["SHA256"]="cab7aeeab63f386cd01ae1d3a82fa5e87fb1165e507098541d238332fee42c78",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Bubupp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.WORKBENCH, 1) or\n        trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n        trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n        trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n        trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1) or\n        trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 5 or failed == 6 then\n            if goodtrade then\n                player:startEvent(224)\n            elseif badtrade then\n                player:startEvent(234)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then                          -- has failed on future npc so disregard previous successful trade\n            player:startEvent(202)\n        elseif progress == 5 or failed == 6 then\n                player:startEvent(211)  -- asking for giant fish bones\n        elseif progress >= 6 or failed >= 7 then\n            player:startEvent(247) -- happy with giant fish bones\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 224 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 5 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 6)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 7)\n        end\n    elseif csid == 234 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 6)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Dodmos.lua"]={["Path"]="scripts/zones/Kazham/npcs/Dodmos.lua",["SHA256"]="9ca66d658cbdfa78f9f16b38db6fa4e50626939283ff9287a0cebb24cf3a94c2",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Dodmos\n--  Starts Quest: Trial Size Trial By Fire\n-- !pos 102.647 -14.999 -97.664 250\n-----------------------------------\nlocal ID = zones[xi.zone.KAZHAM]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        trade:hasItemQty(xi.item.MINI_TUNING_FORK_OF_FIRE, 1) and\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_FIRE) == xi.questStatus.QUEST_ACCEPTED and\n        player:getMainJob() == xi.job.SMN\n    then\n        player:startEvent(287, 0, xi.item.MINI_TUNING_FORK_OF_FIRE, 0, 20)\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local trialSizeFire = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_FIRE)\n\n    if\n        player:getMainLvl() >= 20 and\n        player:getMainJob() == xi.job.SMN and\n        trialSizeFire == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 2\n    then --Requires player to be Summoner at least lvl 20\n        player:startEvent(286, 0, xi.item.MINI_TUNING_FORK_OF_FIRE, 0, 20)     --mini tuning fork, zone, level\n    elseif trialSizeFire == xi.questStatus.QUEST_ACCEPTED then\n        local hasFireFork = player:hasItem(xi.item.MINI_TUNING_FORK_OF_FIRE)\n\n        if hasFireFork then\n            player:startEvent(272) --Dialogue given to remind player to be prepared\n        else\n            player:startEvent(290, 0, xi.item.MINI_TUNING_FORK_OF_FIRE, 0, 20) --Need another mini tuning fork\n        end\n    elseif trialSizeFire == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(289) --Defeated Avatar\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 286 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, 1544) --Mini tuning fork\n        else\n            player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.TRIAL_SIZE_TRIAL_BY_FIRE)\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_FIRE)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_FIRE)\n        end\n    elseif csid == 290 and option == 1 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MINI_TUNING_FORK_OF_FIRE) --Mini tuning fork\n        else\n            player:addItem(xi.item.MINI_TUNING_FORK_OF_FIRE)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MINI_TUNING_FORK_OF_FIRE)\n        end\n    elseif csid == 287 and option == 1 then\n        xi.teleport.to(player, xi.teleport.id.CLOISTER_OF_FLAMES)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Gatih_Mijurabi.lua"]={["Path"]="scripts/zones/Kazham/npcs/Gatih_Mijurabi.lua",["SHA256"]="6bafe25b249732c3dfd369d5bc03b8f3625ac06e0f32df4b10e6006998951a23",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Gatih Mijurabi\n-- !pos 58.249 -13.086 -49.084 250\n-----------------------------------\nlocal ID = zones[xi.zone.KAZHAM]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:getCharVar('BathedInScent') == 1 then\n        if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.PERSONAL_HYGIENE) == xi.questStatus.QUEST_AVAILABLE then\n            player:startEvent(191)\n        elseif player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.PERSONAL_HYGIENE) == xi.questStatus.QUEST_ACCEPTED then\n            player:startEvent(192)\n        else\n            player:startEvent(195)\n        end\n    elseif\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.PERSONAL_HYGIENE) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('BathedInScent') == 0\n    then\n        player:startEvent(193)\n    else\n        player:startEvent(196)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 191 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.PERSONAL_HYGIENE)\n    elseif csid == 193 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MITHRAN_STONE)\n        else\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.PERSONAL_HYGIENE)\n            player:addFame(xi.fameArea.WINDURST, 70)\n            player:addItem(xi.item.MITHRAN_STONE)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MITHRAN_STONE)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Hari_Pakhroib.lua"]={["Path"]="scripts/zones/Kazham/npcs/Hari_Pakhroib.lua",["SHA256"]="d14d58ccf6f1b04379aa277f37c8b8849c0723bd0721fad09a7e10a473891449",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Hari Pakhroib\n-- Starts and Finishes Quest: Greetings to the Guardian\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local guardian = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.GREETINGS_TO_THE_GUARDIAN)\n    local pamamas = player:getCharVar('PamamaVar')\n    local pfame = player:getFameLevel(xi.fameArea.WINDURST)\n    local needToZone = player:needToZone()\n\n    if guardian == xi.questStatus.QUEST_ACCEPTED then\n        if pamamas == 1 then\n            player:startEvent(71) --Finish Quest\n        else\n            player:startEvent(69, 0, 4596) --Reminder Dialogue\n        end\n    elseif guardian == xi.questStatus.QUEST_AVAILABLE and pfame >= 7 then\n        player:startEvent(68, 4596, 4596, 4596) --Start Quest\n    elseif guardian == xi.questStatus.QUEST_COMPLETED and not needToZone then\n        if pamamas == 2 then\n            player:startEvent(71) --Finish quest dialogue (no different csid between initial and repeats)\n        else\n            player:startEvent(72) --Dialogue for after completion of quest\n        end\n    elseif guardian == xi.questStatus.QUEST_COMPLETED and needToZone then\n        player:startEvent(72)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 68 and option == 1 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.GREETINGS_TO_THE_GUARDIAN)\n        player:setCharVar('PamamaVar', 0)\n    elseif csid == 71 then\n        local pamamas = player:getCharVar('PamamaVar')\n        if pamamas == 1 then --First completion of quest; set title and complete quest\n            npcUtil.giveCurrency(player, 'gil', 5000)\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.GREETINGS_TO_THE_GUARDIAN)\n            player:addFame(xi.fameArea.WINDURST, 16)\n            player:addTitle(xi.title.KAZHAM_CALLER)\n            player:setCharVar('PamamaVar', 0)\n            player:needToZone(true)\n        elseif pamamas == 2 then --Repeats of quest\n            npcUtil.giveCurrency(player, 'gil', 5000)\n            player:addFame(xi.fameArea.WINDURST, 16)\n            player:setCharVar('PamamaVar', 0)\n            player:needToZone(true)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Kakapp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Kakapp.lua",["SHA256"]="78bcdf18ad634cae7100832318e91a1b13cde09de4be25528fdcff4f2df5c4d0",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Kakapp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.WYVERN_SKULL, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.WORKBENCH, 1) or\n        trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n        trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n        trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n        trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1) or\n        trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 7 or failed == 8 then\n            if goodtrade then\n                player:startEvent(226)\n            elseif badtrade then\n                player:startEvent(236)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then                          -- has failed on future npc so disregard previous successful trade\n            player:startEvent(204)\n        elseif progress == 7 or failed == 8 then\n                player:startEvent(213)  -- asking for wyvern skull\n        elseif progress >= 8 or failed >= 9 then\n            player:startEvent(249) -- happy with wyvern skull\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 226 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 7 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 8)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 9)\n        end\n    elseif csid == 236 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 8)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Kukupp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Kukupp.lua",["SHA256"]="e5a1a054611f847081b7be123f36ff377ef5e81dc5450ec669fff86b6b7ccc63",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Kukupp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = 44.089, y = -11.000, z = -178.976, wait = 5000 },\n    { x = 40.132, y = -11.000, z = -179.322, wait = 5000 },\n    { x = 44.089, y = -11.000, z = -178.976, wait = 5000 },\n    { x = 40.132, y = -11.000, z = -176.322, wait = 5000 },\n    { x = 46.417, y = -11.000, z = -176.672, wait = 5000 },\n    { x = 40.132, y = -11.000, z = -176.322, wait = 5000 },\n    { x = 46.417, y = -11.000, z = -176.672, wait = 5000 },\n    { x = 40.132, y = -11.000, z = -176.322, wait = 5000 },\n    { x = 46.417, y = -11.000, z = -176.672, wait = 5000 },\n    { x = 40.132, y = -11.000, z = -176.322, wait = 5000 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, bit.bor(xi.path.flag.PATROL, xi.path.flag.RUN))\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.WORKBENCH, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n        trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n        trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n        trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n        trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1) or\n        trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 1 or failed == 2 then\n            if goodtrade then\n                player:startEvent(220)\n            elseif badtrade then\n                player:startEvent(230)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then                          -- has failed on future npc so disregard previous successful trade\n            player:startEvent(198)\n        elseif progress == 1 or failed == 2 then\n            player:startEvent(208)  -- asking for workbench\n        elseif progress >= 2 or failed >= 3 then\n            player:startEvent(243) -- happy with workbench\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 220 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 1 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 2)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 3)\n        end\n    elseif csid == 230 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 2)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Lalapp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Lalapp.lua",["SHA256"]="4409b77eef907cf2a4440b41b141d7682256366af7abe5961d0cdf48d4ff3b5a",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Lalapp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = -63.243702, y = -11.000, z = -97.916130 },\n    { x = -63.970551, z = -97.229286 },\n    { x = -64.771614, z = -96.499062 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, xi.path.flag.PATROL)\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.WORKBENCH, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n        trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n        trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n        trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n        trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n        trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 8 or failed == 9 then\n            if goodtrade then\n                player:startEvent(227)\n            elseif badtrade then\n                player:startEvent(237)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then                          -- has failed on future npc so disregard previous successful trade\n            player:startEvent(205)\n        elseif progress == 8 or failed == 9 then\n                player:startEvent(214)  -- asking for ancient salt\n        elseif progress >= 9 or failed >= 10 then\n            player:startEvent(250) -- happy with ancient salt\n        end\n    else\n        player:startEvent(205)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 227 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 8 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 9)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 10)\n        end\n    elseif csid == 237 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 9)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Lulupp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Lulupp.lua",["SHA256"]="5751345e0e58f08b347882fb0fcec21f97e323587b5079917dd8906412828102",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Lulupp\n-- !pos -26.567 -3.5 -3.544 250\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = -27.457125, y = -3.043032, z = -22.057966 },\n    { x = -27.373426, y = -2.772481, z = -20.974442 },\n    { x = -27.103289, y = -2.500000, z = -17.846378 },\n    { x = -26.864126, z = -15.667570 },\n    { x = -26.532335, z = -16.636086 },\n    { x = -26.505196, z = -15.471632 },\n    { x = -26.509424, z = -14.359641 },\n    { x = -26.564587, z = -4.499783 },\n    { x = -26.574417, z = -5.523735 },\n    { x = -26.580530, z = -6.591716 },\n    { x = -26.583765, z = -8.555706 },\n    { x = -26.501217, z = -16.563267 },\n    { x = -26.504532, z = -15.427269 },\n    { x = -26.509769, z = -14.327281 },\n    { x = -26.565643, z = -4.247434 },\n    { x = -26.573967, z = -5.299402 },\n    { x = -26.579763, z = -6.379386 },\n    { x = -26.580465, z = -8.155381 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, xi.path.flag.PATROL)\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 0 or failed == 1 then\n            if trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) then -- first or second time trading correctly\n                player:startEvent(219)\n            elseif\n                trade:hasItemQty(xi.item.WORKBENCH, 1) or\n                trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n                trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n                trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n                trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n                trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n                trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n                trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1) or\n                trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n            then\n                player:startEvent(229)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if\n        player:getCharVar('BathedInScent') == 1 and\n        opoOpoAndIStatus == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(217, 0, 483)  -- 483 broken mithran fishing rod\n    elseif opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry == 1 then\n            player:startEvent(239) -- gave 1st NPC wrong item instead of \"Broken Mithran Fishing Rod\"\n        elseif retry == 2 then\n            player:startEvent(239, 0, 0, 1) -- gave 2nd NPC wrong item instead of \"Workbench\"\n        elseif retry == 3 then\n            player:startEvent(239, 0, 0, 2) -- gave 3rd NPC wrong item instead of \"Ten of Coins\"\n        elseif retry == 4 then\n            player:startEvent(239, 0, 0, 3) -- gave 4th NPC wrong item instead of \"Sands of silence\"\n        elseif retry == 5 then\n            player:startEvent(239, 0, 0, 4) -- gave 5th NPC wrong item instead of \"Wandering Bulb\"\n        elseif retry == 6 then\n            player:startEvent(239, 0, 0, 5) -- gave 6th NPC wrong item instead of \"Giant Fish Bones\"\n        elseif retry == 7 then\n            player:startEvent(239, 0, 0, 6) -- gave 7th NPC wrong item instead of \"Blackened Toad\"\n        elseif retry == 8 then\n            player:startEvent(239, 0, 0, 7) -- gave 8th NPC wrong item instead of \"Wyvern Skull\"\n        elseif retry == 9 then\n            player:startEvent(239, 0, 0, 8) -- gave 9th NPC wrong item instead of \"Ancient Salt\"\n        elseif retry == 10 then\n            player:startEvent(239, 0, 0, 9) -- gave 10th NPC wrong item instead of \"Lucky Egg\" ... uwot\n        elseif progress == 0 or failed == 1 then\n            player:startEvent(207)  -- asking for rod with Opoppo\n        elseif progress >= 1 or failed >= 2 then\n            player:startEvent(242) -- happy with rod\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 217 and option == 1  then                   -- Opo Opo and I quest start CS\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    elseif csid == 219 then\n        if player:getCharVar('OPO_OPO_PROGRESS') == 0 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 1)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 2)\n        end\n    elseif csid == 229 then                                -- Traded wrong item, saving current progress to not take item up to this point\n        player:setCharVar('OPO_OPO_RETRY', 1)\n    elseif csid == 239 and option == 1 then                -- Traded wrong to another NPC, give a clue\n        player:setCharVar('OPO_OPO_RETRY', 0)\n        player:setCharVar('OPO_OPO_FAILED', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Magriffon.lua"]={["Path"]="scripts/zones/Kazham/npcs/Magriffon.lua",["SHA256"]="c7a7d6d06bff2ad790ea77803c1f7fde78c4bf375441f2085e32c7f710762b47",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Magriffon\n-- Involved in Quest: Gullible's Travels, Even More Gullible's Travels,\n-- Location: (I-7)\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = 60.600, y = -12.000, z = -33.913, wait = 3000 },\n    { z = -38.151, wait = 3000 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, xi.path.flag.PATROL)\nend\n\nentity.onTrade = function(player, npc, trade)\n    if player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.GULLIBLES_TRAVELS) == xi.questStatus.QUEST_ACCEPTED then\n        if trade:getGil() >= player:getCharVar('MAGRIFFON_GIL_REQUEST') then\n            player:startEvent(146)\n        end\n    elseif\n        player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVEN_MORE_GULLIBLES_TRAVELS) == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('EVEN_MORE_GULLIBLES_PROGRESS') == 0\n    then\n        if trade:getGil() >= 35000 then\n            player:startEvent(150, 0, 256)\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local gulliblesTravelsStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.GULLIBLES_TRAVELS)\n    local evenmoreTravelsStatus  = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVEN_MORE_GULLIBLES_TRAVELS)\n\n    if gulliblesTravelsStatus == xi.questStatus.QUEST_ACCEPTED then\n        local magriffonGilRequest = player:getCharVar('MAGRIFFON_GIL_REQUEST')\n        player:startEvent(145, 0, magriffonGilRequest)\n    elseif\n        gulliblesTravelsStatus == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 6\n    then\n        local gil = math.randomInt(10, 30) * 1000\n        player:setCharVar('MAGRIFFON_GIL_REQUEST', gil)\n        player:startEvent(144, 0, gil)\n    elseif\n        evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('EVEN_MORE_GULLIBLES_PROGRESS') == 0\n    then\n        player:startEvent(149, 0, 256, 0, 0, 0, 35000)\n    elseif\n        evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('EVEN_MORE_GULLIBLES_PROGRESS') == 1\n    then\n        player:startEvent(151)\n    elseif\n        evenmoreTravelsStatus == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('EVEN_MORE_GULLIBLES_PROGRESS') == 2\n    then\n        player:startEvent(152, 0, 1144, 256)\n    elseif gulliblesTravelsStatus == xi.questStatus.QUEST_COMPLETED then\n        if\n            evenmoreTravelsStatus == xi.questStatus.QUEST_AVAILABLE and\n            player:getFameLevel(xi.fameArea.WINDURST) >= 7 and\n            not player:needToZone()\n        then\n            player:startEvent(148, 0, 256, 0, 0, 35000)\n        else\n            player:startEvent(147)\n        end\n\n    else\n        player:startEvent(143)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 144 and option == 1 then                     -- Gullible's Travels: First CS\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.GULLIBLES_TRAVELS)\n    elseif csid == 146 then                                  -- Gullible's Travels: Final CS\n        player:confirmTrade()\n        player:delGil(player:getCharVar('MAGRIFFON_GIL_REQUEST'))\n        player:setCharVar('MAGRIFFON_GIL_REQUEST', 0)\n        player:addFame(xi.fameArea.WINDURST, 30)\n        player:setTitle(xi.title.GULLIBLES_TRAVELS)\n        player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.GULLIBLES_TRAVELS)\n        player:needToZone(true)\n    elseif csid == 148 and option == 1 then                  -- Even More Guillible's Travels First CS\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVEN_MORE_GULLIBLES_TRAVELS)\n    elseif csid == 150 then                                  -- Even More Guillible's Travels Second CS\n        player:confirmTrade()\n        player:delGil(35000)\n        player:setCharVar('EVEN_MORE_GULLIBLES_PROGRESS', 1)\n        player:setTitle(xi.title.EVEN_MORE_GULLIBLES_TRAVELS)\n        npcUtil.giveKeyItem(player, xi.keyItem.TREASURE_MAP)\n    elseif csid == 152 then\n        player:setCharVar('EVEN_MORE_GULLIBLES_PROGRESS', 0)\n        player:addFame(xi.fameArea.WINDURST, 70)\n        player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.EVEN_MORE_GULLIBLES_TRAVELS)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Mumupp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Mumupp.lua",["SHA256"]="dfe87d63d779558e9f06d0a047da34d4ec328c3a91ddf8c61142b78014941763",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Mumupp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = 94.732452, y = -15.000000, z = -114.034622 },\n    { x = 94.210846, z = -114.989388 },\n    { x = 93.508865, z = -116.274101 },\n    { x = 94.584877, z = -116.522118 },\n    { x = 95.646988, z = -116.468452 },\n    { x = 94.613518, z = -116.616562 },\n    { x = 93.791100, z = -115.858505 },\n    { x = 94.841835, z = -116.108437 },\n    { x = 93.823380, z = -116.712860 },\n    { x = 94.986847, z = -116.571831 },\n    { x = 94.165512, z = -115.965698 },\n    { x = 95.005806, z = -116.519707 },\n    { x = 93.935555, z = -116.706291 },\n    { x = 94.943497, z = -116.578346 },\n    { x = 93.996826, z = -115.932816 },\n    { x = 95.060165, z = -116.180840 },\n    { x = 94.081062, z = -115.923836 },\n    { x = 95.246490, z = -116.215691 },\n    { x = 94.234077, z = -115.960793 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, xi.path.flag.PATROL)\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.WORKBENCH, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n        trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n        trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n        trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n        trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1) or\n        trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 2 or failed == 3 then\n            if goodtrade then\n                player:startEvent(221)\n            elseif badtrade then\n                player:startEvent(231)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then -- has failed on future npc so disregard previous successful trade\n            player:startEvent(199)\n        elseif progress == 2 or failed == 3 then\n            player:startEvent(209)  -- asking for ten of coins\n        elseif progress >= 3 or failed >= 4 then\n            player:startEvent(244) -- happy with ten of coins\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 221 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 2 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 3)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 4)\n        end\n    elseif csid == 231 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 3)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Nenepp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Nenepp.lua",["SHA256"]="9dc4495a35158c349995599487ffbe3d048e76c0b6dbbef90ba2f538405831a2",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Nenepp\n-----------------------------------\nlocal ID = zones[xi.zone.KAZHAM]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = 29.014000, y = -11.00000, z = -183.884000 },\n    { x = 31.023000, z = -183.538000 },\n    { x = 33.091000, z = -183.738000 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, xi.path.flag.PATROL)\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.WORKBENCH, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n        trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n        trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n        trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n        trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n        trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 9 or failed == 10 then\n            if goodtrade then\n                player:startEvent(241)\n            elseif badtrade then\n                player:startEvent(238)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then                          -- has failed on future npc so disregard previous successful trade\n            player:startEvent(206)\n        elseif progress == 9 or failed == 10 then\n                player:startEvent(212)  -- asking for lucky egg\n        elseif progress >= 10 or failed >= 11 then\n            player:startEvent(250) -- happy with lucky egg\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 241 then    -- correct trade, finished quest and receive opo opo crown and 3 pamamas\n        if player:getFreeSlotsCount() >= 4 then\n            player:tradeComplete()\n            player:addFame(xi.fameArea.WINDURST, 70)\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n            player:addItem(xi.item.OPO_OPO_CROWN)   -- opo opo crown\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.OPO_OPO_CROWN)\n            player:addItem(xi.item.BUNCH_OF_PAMAMAS, 3)  -- 3 pamamas\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.BUNCH_OF_PAMAMAS, 3)\n            player:setCharVar('OPO_OPO_PROGRESS', 0)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n            player:setCharVar('OPO_OPO_RETRY', 0)\n            player:setTitle(xi.title.KING_OF_THE_OPO_OPOS)\n        else\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED)\n        end\n    elseif csid == 238 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 10)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Popopp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Popopp.lua",["SHA256"]="09334e4152a00ea38df55c05b5e5a6221f7dce98854c945b936f7aa6bec43e00",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Popopp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.WANDERING_BULB, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.WORKBENCH, 1) or\n        trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n        trade:hasItemQty(xi.item.BLACKENED_TOAD, 1) or\n        trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n        trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1) or\n        trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 4 or failed == 5 then\n            if goodtrade then\n                player:startEvent(223)\n            elseif badtrade then\n                player:startEvent(233)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then                          -- has failed on future npc so disregard previous successful trade\n            player:startEvent(201)\n        elseif progress == 4 or failed == 5 then\n                player:startEvent(210)  -- asking for wandering bulb\n        elseif progress >= 5 or failed >= 6 then\n            player:startEvent(246) -- happy with wandering bulb\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 223 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 4 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 5)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 6)\n        end\n    elseif csid == 233 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 5)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Rauteinot.lua"]={["Path"]="scripts/zones/Kazham/npcs/Rauteinot.lua",["SHA256"]="50162764158706f0ef5fb781653f8aeeb8ee8c8304e32470079e21d7a6bc46ec",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Rauteinot\n-- Starts and Finishes Quest: Missionary Man\n-- !pos -42 -10 -89 250\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getCharVar('MissionaryManVar') == 1 and\n        trade:hasItemQty(xi.item.SLAB_OF_ELSHIMO_MARBLE, 1) and\n        trade:getItemCount() == 1\n    then\n        player:startEvent(139) -- Trading elshimo marble\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local missionaryMan = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.MISSIONARY_MAN)\n    local missionaryManVar = player:getCharVar('MissionaryManVar')\n\n    if\n        missionaryMan == xi.questStatus.QUEST_AVAILABLE and\n        player:getFameLevel(xi.fameArea.WINDURST) >= 3\n    then\n        player:startEvent(137, 0, xi.item.SLAB_OF_ELSHIMO_MARBLE) -- Start quest \"Missionary Man\"\n    elseif missionaryMan == xi.questStatus.QUEST_ACCEPTED and missionaryManVar == 1 then\n        player:startEvent(138, 0, xi.item.SLAB_OF_ELSHIMO_MARBLE) -- During quest (before trade marble) \"Missionary Man\"\n    elseif\n        missionaryMan == xi.questStatus.QUEST_ACCEPTED and\n        (missionaryManVar == 2 or missionaryManVar == 3)\n    then\n        player:startEvent(140) -- During quest (after trade marble) \"Missionary Man\"\n    elseif missionaryMan == xi.questStatus.QUEST_ACCEPTED and missionaryManVar == 4 then\n        player:startEvent(141) -- Finish quest \"Missionary Man\"\n    elseif missionaryMan == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(142) -- New standard dialog\n    else\n        player:startEvent(136) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 137 and option == 1 then\n        player:addQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.MISSIONARY_MAN)\n        player:setCharVar('MissionaryManVar', 1)\n    elseif csid == 139 then\n        player:setCharVar('MissionaryManVar', 2)\n        npcUtil.giveKeyItem(player, xi.keyItem.RAUTEINOTS_PARCEL)\n        player:tradeComplete()\n    elseif csid == 141 then\n        if npcUtil.giveItem(player, xi.item.SCROLL_OF_TELEPORT_YHOAT) then\n            player:setCharVar('MissionaryManVar', 0)\n            player:delKeyItem(xi.keyItem.SUBLIME_STATUE_OF_THE_GODDESS)\n            player:addFame(xi.fameArea.WINDURST, 30)\n            player:completeQuest(xi.questLog.OUTLANDS, xi.quest.id.outlands.MISSIONARY_MAN)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Roropp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Roropp.lua",["SHA256"]="a7ae1ae004c0f96caabebe3d1030a0343cf961c721f27111dd6633585551bddf",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Roropp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = 17.314, y = -8.000, z = -110.064, wait = 5000 },\n    { x = 13.323, z = -102.821, wait = 5000 },\n    { x = 17.314, z = -110.064, wait = 5000 },\n    { x = 12.576, z = -113.211, wait = 5000 },\n    { x = 17.314, z = -110.064, wait = 5000 },\n    { x = 13.323, z = -102.821, wait = 5000 },\n    { x = 17.388, z = -99.219, wait = 5000 },\n    { x = 15.511, z = -112.292, wait = 5000 },\n    { x = 13.605, z = -109.863, wait = 5000 },\n    { x = 15.511, z = -112.292, wait = 5000 },\n    { x = 13.605, z = -109.863, wait = 5000 },\n    { x = 17.388, z = -99.219, wait = 5000 },\n    { x = 13.323, z = -102.821, wait = 5000 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, bit.bor(xi.path.flag.PATROL, xi.path.flag.RUN))\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n  