sands of silence\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 222 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 3 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 4)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 5)\n        end\n    elseif csid == 232 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 4)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Kazham/npcs/Tatapp.lua"]={["Path"]="scripts/zones/Kazham/npcs/Tatapp.lua",["SHA256"]="0bb01880e285d75237d9bcdb05590992d94d49bfb9ea0766efa831423a96d8b8",["Text"]="-----------------------------------\n-- Area: Kazham\n--  NPC: Tatapp\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal pathNodes =\n{\n    { x = 0.532, y = -8.000, z = -87.569 },\n    { x = 7.720, z = -88.972 },\n    { x = 8.935, z = -90.178 },\n    { x = 10.142, z = -91.488 },\n    { x = 11.468, z = -93.482 },\n    { x = 12.613, z = -96.828 },\n    { x = 13.596, z = -101.027 },\n    { x = 16.654, y = -8.096, z = -117.617 },\n    { x = 16.574, y = -9.385, z = -123.560 },\n    { x = 16.313, y = -9.873, z = -128.798 },\n    { x = 15.083, y = -10.192, z = -133.932 },\n    { x = 13.719, y = -10.710, z = -139.264 },\n    { x = 13.938, y = -10.257, z = -142.789 },\n    { x = 16.414, y = -10.012, z = -145.393 },\n    { x = 20.226, y = -10.721, z = -146.769 },\n    { x = 25.940, y = -11.018, z = -148.466 },\n    { x = 43.709, y = -11.000, z = -152.974 },\n    { x = 48.625, z = -150.807 },\n    { x = 57.275, y = -11.135, z = -145.113 },\n    { x = 58.448, y = -11.250, z = -141.982 },\n    { x = 60.327, y = -11.248, z = -138.212 },\n    { x = 64.383, y = -11.931, z = -133.202 },\n    { x = 68.261, y = -12.894, z = -130.81