y = -8.105, z = -87.539 },\n}\n\nentity.onSpawn = function(npc)\n    npc:initNpcAi()\n    npc:setPos(xi.path.first(pathNodes))\n    npc:pathThrough(pathNodes, xi.path.flag.PATROL)\nend\n\nentity.onTrade = function(player, npc, trade)\n    -- item IDs\n    -- 483       Broken Mithran Fishing Rod\n    -- 22        Workbench\n    -- 1008      Ten of Coins\n    -- 1157      Sands of Silence\n    -- 1158      Wandering Bulb\n    -- 904       Giant Fish Bones\n    -- 4599      Blackened Toad\n    -- 905       Wyvern Skull\n    -- 1147      Ancient Salt\n    -- 4600      Lucky Egg\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local goodtrade = trade:hasItemQty(xi.item.BLACKENED_TOAD, 1)\n    local badtrade = trade:hasItemQty(xi.item.BROKEN_MITHRAN_FISHING_ROD, 1) or\n        trade:hasItemQty(xi.item.WORKBENCH, 1) or\n        trade:hasItemQty(xi.item.HANDFUL_OF_THE_SANDS_OF_SILENCE, 1) or\n        trade:hasItemQty(xi.item.WANDERING_BULB, 1) or\n        trade:hasItemQty(xi.item.SET_OF_GIANT_FISH_BONES, 1) or\n        trade:hasItemQty(xi.item.TEN_OF_COINS_CARD, 1) or\n        trade:hasItemQty(xi.item.WYVERN_SKULL, 1) or\n        trade:hasItemQty(xi.item.ROCK_OF_ANCIENT_SALT, 1) or\n        trade:hasItemQty(xi.item.LUCKY_EGG, 1)\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if progress == 6 or failed == 7 then\n            if goodtrade then\n                player:startEvent(225)\n            elseif badtrade then\n                player:startEvent(235)\n            end\n        end\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local opoOpoAndIStatus = player:getQuestStatus(xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_OPO_OPO_AND_I)\n    local progress = player:getCharVar('OPO_OPO_PROGRESS')\n    local failed = player:getCharVar('OPO_OPO_FAILED')\n    local retry = player:getCharVar('OPO_OPO_RETRY')\n\n    if opoOpoAndIStatus == xi.questStatus.QUEST_ACCEPTED then\n        if retry >= 1 then                          -- has failed on future npc so disregard previous successful trade\n            player:startEvent(203)\n        elseif progress == 6 or failed == 7 then\n                player:startEvent(212)  -- asking for blackened toad\n        elseif progress >= 7 or failed >= 8 then\n            player:startEvent(248) -- happy with blackened toad\n        end\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 225 then    -- correct trade, onto next opo\n        if player:getCharVar('OPO_OPO_PROGRESS') == 6 then\n            player:tradeComplete()\n            player:setCharVar('OPO_OPO_PROGRESS', 7)\n            player:setCharVar('OPO_OPO_FAILED', 0)\n        else\n            player:setCharVar('OPO_OPO_FAILED', 8)\n        end\n    elseif csid == 235 then              -- wrong trade, restart at first opo\n        player:setCharVar('OPO_OPO_FAILED', 1)\n        player:setCharVar('OPO_OPO_RETRY', 7)\n    end\nend\n\nreturn entity\n"},["scripts/zones/La_Theine_Plateau/npcs/Faurbellant.lua"]={["Path"]="scripts/zones/La_Theine_Plateau/npcs/Faurbellant.lua",["SHA256"]="2b8532533b3d08974866045fd76bac48e5b4e74e102d8f204293074fa93d0044",["Text"]="-----------------------------------\n-- Area: La Theine Plateau\n--  NPC: Faurbellant\n-- Involved in Quest: Gates of Paradise\n-- !pos 484 24 -89 102\n-----------------------------------\nlocal ID = zones[xi.zone.LA_THEINE_PLATEAU]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local gates = player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.GATES_TO_PARADISE)\n    if gates == xi.questStatus.QUEST_COMPLETED then\n        player:showText(npc, ID.text.FAURBELLANT_4)\n    elseif gates == xi.questStatus.QUEST_ACCEPTED then\n        if player:hasKeyItem(xi.keyItem.SCRIPTURE_OF_WIND) then\n            player:showText(npc, ID.text.FAURBELLANT_2, 0, xi.keyItem.SCRIPTURE_OF_WIND)\n            player:delKeyItem(xi.keyItem.SCRIPTURE_OF_WIND)\n            npcUtil.giveKeyItem(player, xi.keyItem.SCRIPTURE_OF_WATER)\n        else\n            player:showText(npc, ID.text.FAURBELLANT_3, xi.keyItem.SCRIPTURE_OF_WATER)\n        end\n    else\n        player:showText(npc, ID.text.FAURBELLANT_1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/Domenic.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/Domenic.lua",["SHA256"]="7c9c994a8f919b8bd5a1f56b51a958b6cc25b7ba74980040b5221decf7104e3f",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Domenic\n-- BCNM/KSNM Teleporter\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.BEYOND_INFINITY) then\n        player:startEvent(10115, player:getGil())\n    else\n        player:startEvent(10116)\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 10115 then\n        if option == 1 and player:getGil() >= 750 then\n            player:delGil(750)\n            xi.teleport.to(player, xi.teleport.id.GHELSBA_HUT)\n        elseif option == 2 and player:getGil() >= 750 then\n            player:delGil(750)\n            player:setPos(0, 0, 0, 0, 139)\n        elseif option == 3 and player:getGil() >= 750 then\n            player:delGil(750)\n            player:setPos(0, 0, 0, 0, 144)\n        elseif option == 4 and player:getGil() >= 750 then\n            player:delGil(750)\n            player:setPos(0, 0, 0, 0, 146)\n        elseif option == 5 and player:getGil() >= 1000 then\n            player:delGil(1000)\n            player:setPos(0, 0, 0, 0, 206)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/Naruru.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/Naruru.lua",["SHA256"]="0c00e4bf5c6ef35fd82362d0deb3249ca0d94ba78d01cc0ecaf286d7b9fccdca",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Naruru\n-- Starts and Finishes Quests: Cook's Pride\n-- !pos -56 0.1 -138 245\n-----------------------------------\nlocal ID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local cooksPride     = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COOKS_PRIDE)\n    local theKindCardian = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN)\n\n    if\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_WONDER_MAGIC_SET) == xi.questStatus.QUEST_COMPLETED and\n        cooksPride == xi.questStatus.QUEST_AVAILABLE\n    then\n        if player:getCharVar('CooksPrideVar') == 0 then\n            player:startEvent(189) -- Start quest \"Cook's pride\" Long CS\n        else\n            player:startEvent(188) -- Start quest \"Cook's pride\" Short CS\n        end\n\n    elseif\n        cooksPride == xi.questStatus.QUEST_ACCEPTED and\n        not player:hasKeyItem(xi.keyItem.SUPER_SOUP_POT)\n    then\n        player:startEvent(186) -- During quest \"Cook's pride\"\n\n    elseif player:hasKeyItem(xi.keyItem.SUPER_SOUP_POT) then\n        player:startEvent(187) -- Finish quest \"Cook's pride\"\n\n    elseif\n        cooksPride == xi.questStatus.QUEST_COMPLETED and\n        theKindCardian == xi.questStatus.QUEST_AVAILABLE\n    then\n        if player:getCharVar('theLostCardianVar') == 0 then\n            player:startEvent(31) -- During quests \"The lost cardian\"\n        else\n            player:startEvent(71) -- During quests \"The lost cardian\"\n        end\n\n    elseif\n        cooksPride == xi.questStatus.QUEST_COMPLETED and\n        theKindCardian ~= xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(71) -- During quests \"The kind cardien\"\n\n    elseif theKindCardian == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(72) -- New standard dialog after the quest \"The kind cardien\"\n\n    else\n        player:startEvent(98) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if\n        (csid == 189 or csid == 188) and\n        option == 0\n    then\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.COOKS_PRIDE)\n\n    elseif csid == 189 and option == 1 then\n        player:setCharVar('CooksPrideVar', 1)\n\n    elseif csid == 187 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MYTHRIL_RING)\n        else\n            player:addTitle(xi.title.MERCY_ERRAND_RUNNER)\n            player:delKeyItem(xi.keyItem.SUPER_SOUP_POT)\n            player:setCharVar('CooksPrideVar', 0)\n            npcUtil.giveCurrency(player, 'gil', 3000)\n            player:addItem(xi.item.MYTHRIL_RING)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MYTHRIL_RING)\n            player:addFame(xi.fameArea.SANDORIA, 13)\n            player:addFame(xi.fameArea.BASTOK, 13)\n            player:addFame(xi.fameArea.WINDURST, 13)\n            player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.COOKS_PRIDE)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/Panta-Putta.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/Panta-Putta.lua",["SHA256"]="c595e65d90c8b9e0b80141bd1c832cfb33da0c1ffcb2fedc946cd8f801f87861",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Panta-Putta\n-- Starts and Finishes Quest: The Wonder Magic Set, The kind cardian\n-- Involved in Quests: The Lost Cardian\n-- !pos -61 0 -140 245\n-----------------------------------\nlocal ID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local theWonderMagicSet = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_WONDER_MAGIC_SET)\n    local hasWonderMagicSet = player:hasKeyItem(xi.keyItem.WONDER_MAGIC_SET)\n    local theKindCardian    = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN)\n\n    if\n        player:getFameLevel(xi.fameArea.JEUNO) >= 4 and\n        theWonderMagicSet == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:startEvent(77) -- Start quest \"The wonder magic set\"\n\n    elseif\n        theWonderMagicSet == xi.questStatus.QUEST_ACCEPTED and\n        not hasWonderMagicSet\n    then\n        player:startEvent(55) -- During quest \"The wonder magic set\"\n\n    elseif hasWonderMagicSet then\n        player:startEvent(33) -- Finish quest \"The wonder magic set\"\n\n    elseif\n        theWonderMagicSet == xi.questStatus.QUEST_COMPLETED and\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COOKS_PRIDE) ~= xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(40) -- Standard dialog\n\n    elseif\n        theWonderMagicSet == xi.questStatus.QUEST_COMPLETED and\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_LOST_CARDIAN) == xi.questStatus.QUEST_AVAILABLE\n    then\n        if player:getCharVar('theLostCardianVar') >= 1 then\n            player:startEvent(30) -- Second dialog for \"The lost cardien\" quest\n        else\n            player:startEvent(40) -- Standard dialog\n        end\n\n    elseif\n        theKindCardian == xi.questStatus.QUEST_ACCEPTED and\n        player:getCharVar('theKindCardianVar') == 2\n    then\n        player:startEvent(35) -- Finish quest \"The kind cardien\"\n\n    elseif theKindCardian == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(76) -- New standard dialog after \"The kind cardien\"\n\n    else\n        player:startEvent(78) -- Base standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 77 and option == 1 then\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_WONDER_MAGIC_SET)\n    elseif csid == 33 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.MYTHRIL_EARRING)\n        else\n            player:addTitle(xi.title.FOOLS_ERRAND_RUNNER)\n            player:delKeyItem(xi.keyItem.WONDER_MAGIC_SET)\n            player:addItem(xi.item.MYTHRIL_EARRING)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.MYTHRIL_EARRING)\n            player:addFame(xi.fameArea.SANDORIA, 13)\n            player:addFame(xi.fameArea.BASTOK, 13)\n            player:addFame(xi.fameArea.WINDURST, 13)\n            player:needToZone(true)\n            player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_WONDER_MAGIC_SET)\n        end\n    elseif csid == 30 then\n        player:setCharVar('theLostCardianVar', 2)\n    elseif csid == 35 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.GREEN_CAPE)\n        else\n            player:addTitle(xi.title.BRINGER_OF_BLISS)\n            player:delKeyItem(xi.keyItem.TWO_OF_SWORDS)\n            player:setCharVar('theKindCardianVar', 0)\n            player:addItem(xi.item.GREEN_CAPE)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.GREEN_CAPE) -- Green Cape\n            player:addFame(xi.fameArea.SANDORIA, 13)\n            player:addFame(xi.fameArea.BASTOK, 13)\n            player:addFame(xi.fameArea.WINDURST, 13)\n            player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN)\n        end\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/Sutarara.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/Sutarara.lua",["SHA256"]="84d2b2ca1d9e80b21fe2a28e29b85fb2b14a852403e39db6cdedc20a0656f256",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Sutarara\n-- Involved in Quests: Tenshodo Membership\n-- !pos 30 0.1 -2 245\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    if player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.TENSHODO_MEMBERSHIP) then\n        player:startEvent(211)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/Teigero-Bangero.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/Teigero-Bangero.lua",["SHA256"]="b34523622c50a368a0b5958a00eccee8e78b2e00b3ac3e947ab20e3b5a5d5745",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Teigero-Bangero\n-- Involved in Quests: The Lost Cardian\n-- !pos -58 0 -143 245\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrigger = function(player, npc)\n    local theKindCardian = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_KIND_CARDIAN)\n\n    if player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_WONDER_MAGIC_SET) == xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(34) -- Base Standard CS & dialog\n    elseif player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.COOKS_PRIDE) ~= xi.questStatus.QUEST_COMPLETED then\n        local rand = math.randomInt(1, 2)\n        if rand == 1 then\n            player:startEvent(75) -- During Panta and Naruru Quests\n        else\n            player:startEvent(32) -- Same\n        end\n    elseif player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_LOST_CARDIAN) == xi.questStatus.QUEST_AVAILABLE then\n        if player:getCharVar('theLostCardianVar') == 0 then\n            player:startEvent(29) -- First dialog for \"The lost cardian\" quest\n        else\n            player:startEvent(66)\n        end\n    elseif theKindCardian == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(66) -- During quest \"The kind cardien\"\n    elseif theKindCardian == xi.questStatus.QUEST_COMPLETED then\n        player:startEvent(67) -- New standard dialog after \"The kind cardian\"\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 29 then\n        player:setCharVar('theLostCardianVar', 1)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/Vingijard.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/Vingijard.lua",["SHA256"]="dfcd88a507c6a872b0f29dfd35fe0c3253d6bf77ee5e18f1986833ba436a2919",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Vingijard\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nlocal jobGearTable =\n{\n    -- [job ID]  = { Weapon,             Head,                  Body,                    Hands,                     Legs,                     Feet                      },\n    [xi.job.WAR] = { xi.item.RAZOR_AXE,  xi.item.FIGHTERS_MASK, xi.item.FIGHTERS_LORICA, xi.item.FIGHTERS_MUFFLERS, xi.item.FIGHTERS_CUISSES, xi.item.FIGHTERS_CALLIGAE },\n    [xi.job.MNK] = { xi.item.BEAT_CESTI, xi.item.TEMPLE_CROWN,  xi.item.TEMPLE_CYCLAS,   xi.item.TEMPLE_GLOVES,     xi.item.TEMPLE_HOSE,      xi.item.TEMPLE_GAITERS    },\n    -- [xi.job.WHM] = {  },\n    -- [xi.job.BLM] = {  },\n    -- [xi.job.RDM] = {  },\n    -- [xi.job.THF] = {  },\n    -- [xi.job.PLD] = {  },\n    -- [xi.job.DRK] = {  },\n    -- [xi.job.BST] = {  },\n    -- [xi.job.BRD] = {  },\n    -- [xi.job.RNG] = {  },\n    -- [xi.job.SAM] = {  },\n    -- [xi.job.NIN] = {  },\n    -- [xi.job.DRG] = {  },\n    -- [xi.job.SMN] = {  },\n    -- [xi.job.BLU] = {  },\n    -- [xi.job.COR] = {  },\n    -- [xi.job.PUP] = {  },\n    -- [xi.job.DNC] = {  },\n    -- [xi.job.SCH] = {  },\n    -- [xi.job.GEO] = {  },\n    -- [xi.job.RUN] = {  },\n}\n\nlocal jobQuestsTable =\n{\n\n    [xi.job.WAR] =\n    {\n        [1] = { xi.questLog.BASTOK, xi.quest.id.bastok.THE_DOORMAN             },\n        [2] = { xi.questLog.BASTOK, xi.quest.id.bastok.THE_TALEKEEPERS_TRUTH   },\n        [3] = { xi.questLog.BASTOK, xi.quest.id.bastok.THE_TALEKEEPERS_GIFT    },\n        [4] = { xi.questLog.JEUNO,  xi.quest.id.jeuno.BORGHERTZS_WARRING_HANDS },\n    },\n    [xi.job.MNK] =\n    {\n        [1] = { xi.questLog.BASTOK, xi.quest.id.bastok.GHOSTS_OF_THE_PAST       },\n        [2] = { xi.questLog.BASTOK, xi.quest.id.bastok.THE_FIRST_MEETING        },\n        [3] = { xi.questLog.BASTOK, xi.quest.id.bastok.TRUE_STRENGTH            },\n        [4] = { xi.questLog.JEUNO,  xi.quest.id.jeuno.BORGHERTZS_STRIKING_HANDS },\n    },\n    [xi.job.WHM] =\n    {\n        [1] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.MESSENGER_FROM_BEYOND      },\n        [2] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.PRELUDE_OF_BLACK_AND_WHITE },\n        [3] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.PIEUJES_DECISION           },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_HEALING_HANDS      },\n    },\n    [xi.job.BLM] =\n    {\n        [1] = { xi.questLog.WINDURST, xi.quest.id.windurst.THE_THREE_MAGI          },\n        [2] = { xi.questLog.WINDURST, xi.quest.id.windurst.RECOLLECTIONS           },\n        [3] = { xi.questLog.WINDURST, xi.quest.id.windurst.THE_ROOT_OF_THE_PROBLEM },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_SORCEROUS_HANDS },\n    },\n    [xi.job.RDM] =\n    {\n        [1] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.THE_CRIMSON_TRIAL        },\n        [2] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.ENVELOPED_IN_DARKNESS    },\n        [3] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.PEACE_FOR_THE_SPIRIT     },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_VERMILLION_HANDS },\n    },\n    [xi.job.THF] =\n    {\n        [1] = { xi.questLog.WINDURST, xi.quest.id.windurst.THE_TENSHODO_SHOWDOWN  },\n        [2] = { xi.questLog.WINDURST, xi.quest.id.windurst.AS_THICK_AS_THIEVES    },\n        [3] = { xi.questLog.WINDURST, xi.quest.id.windurst.HITTING_THE_MARQUISATE },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_SNEAKY_HANDS   },\n    },\n    [xi.job.PLD] =\n    {\n        [1] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.SHARPENING_THE_SWORD   },\n        [2] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.A_BOYS_DREAM           },\n        [3] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.UNDER_OATH             },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_STALWART_HANDS },\n    },\n    [xi.job.DRK] =\n    {\n        [1] = { xi.questLog.BASTOK, xi.quest.id.bastok.DARK_LEGACY             },\n        [2] = { xi.questLog.BASTOK, xi.quest.id.bastok.DARK_PUPPET             },\n        [3] = { xi.questLog.BASTOK, xi.quest.id.bastok.BLADE_OF_EVIL           },\n        [4] = { xi.questLog.JEUNO,  xi.quest.id.jeuno.BORGHERTZS_SHADOWY_HANDS },\n    },\n    [xi.job.BST] =\n    {\n        [1] = { xi.questLog.JEUNO, xi.quest.id.jeuno.WINGS_OF_GOLD         },\n        [2] = { xi.questLog.JEUNO, xi.quest.id.jeuno.SCATTERED_INTO_SHADOW },\n        [3] = { xi.questLog.JEUNO, xi.quest.id.jeuno.A_NEW_DAWN            },\n        [4] = { xi.questLog.JEUNO, xi.quest.id.jeuno.BORGHERTZS_WILD_HANDS },\n    },\n    [xi.job.BRD] =\n    {\n        [1] = { xi.questLog.JEUNO, xi.quest.id.jeuno.PAINFUL_MEMORY              },\n        [2] = { xi.questLog.JEUNO, xi.quest.id.jeuno.THE_REQUIEM                 },\n        [3] = { xi.questLog.JEUNO, xi.quest.id.jeuno.THE_CIRCLE_OF_TIME          },\n        [4] = { xi.questLog.JEUNO, xi.quest.id.jeuno.BORGHERTZS_HARMONIOUS_HANDS },\n    },\n    [xi.job.RNG] =\n    {\n        [1] = { xi.questLog.WINDURST, xi.quest.id.windurst.SIN_HUNTING           },\n        [2] = { xi.questLog.WINDURST, xi.quest.id.windurst.FIRE_AND_BRIMSTONE    },\n        [3] = { xi.questLog.WINDURST, xi.quest.id.windurst.UNBRIDLED_PASSION     },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_CHASING_HANDS },\n    },\n    [xi.job.SAM] =\n    {\n        [1] = { xi.questLog.OUTLANDS, xi.quest.id.outlands.THE_SACRED_KATANA   },\n        [2] = { xi.questLog.OUTLANDS, xi.quest.id.outlands.YOMI_OKURI          },\n        [3] = { xi.questLog.OUTLANDS, xi.quest.id.outlands.A_THIEF_IN_NORG     },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_LOYAL_HANDS },\n    },\n    [xi.job.NIN] =\n    {\n        [1] = { xi.questLog.OUTLANDS, xi.quest.id.outlands.TWENTY_IN_PIRATE_YEARS },\n        [2] = { xi.questLog.OUTLANDS, xi.quest.id.outlands.I_LL_TAKE_THE_BIG_BOX  },\n        [3] = { xi.questLog.OUTLANDS, xi.quest.id.outlands.TRUE_WILL              },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_LURKING_HANDS  },\n    },\n    [xi.job.DRG] =\n    {\n        [1] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.A_CRAFTSMANS_WORK    },\n        [2] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.CHASING_QUOTAS       },\n        [3] = { xi.questLog.SANDORIA, xi.quest.id.sandoria.KNIGHT_STALKER       },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_DRAGON_HANDS },\n    },\n    [xi.job.SMN] =\n    {\n        [1] = { xi.questLog.WINDURST, xi.quest.id.windurst.THE_PUPPET_MASTER     },\n        [2] = { xi.questLog.WINDURST, xi.quest.id.windurst.CLASS_REUNION         },\n        [3] = { xi.questLog.WINDURST, xi.quest.id.windurst.CARBUNCLE_DEBACLE     },\n        [4] = { xi.questLog.JEUNO,    xi.quest.id.jeuno.BORGHERTZS_CALLING_HANDS },\n    },\n    [xi.job.BLU] =\n    {\n        [1] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.BEGINNINGS      },\n        [2] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OMENS           },\n        [3] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS },\n    },\n    [xi.job.COR] =\n    {\n        [1] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.EQUIPPED_FOR_ALL_OCCASIONS     },\n        [2] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.NAVIGATING_THE_UNFRIENDLY_SEAS },\n        [3] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.AGAINST_ALL_ODDS               },\n    },\n    [xi.job.PUP] =\n    {\n        [1] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.THE_WAYWARD_AUTOMATION },\n        [2] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.OPERATION_TEATIME      },\n        [3] = { xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PUPPETMASTER_BLUES     },\n    },\n    [xi.job.DNC] =\n    {\n        [1] = { xi.questLog.JEUNO, xi.quest.id.jeuno.THE_UNFINISHED_WALTZ },\n        [2] = { xi.questLog.JEUNO, xi.quest.id.jeuno.THE_ROAD_TO_DIVADOM  },\n        [3] = { xi.questLog.JEUNO, xi.quest.id.jeuno.COMEBACK_QUEEN       },\n    },\n    [xi.job.SCH] =\n    {\n        [1] = { xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.ON_SABBATICAL    },\n        [2] = { xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.DOWNWARD_HELIX   },\n        [3] = { xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SEEING_BLOOD_RED },\n    },\n    [xi.job.GEO] =\n    {\n    },\n    [xi.job.RUN] =\n    {\n    },\n}\n\nlocal jobCofferTable =\n{\n    [xi.job.WAR] = { '[AF]ZilartCoffer',  1,  2 },\n    [xi.job.MNK] = { '[AF]ZilartCoffer',  3,  4 },\n    [xi.job.WHM] = { '[AF]ZilartCoffer',  5,  6 },\n    [xi.job.BLM] = { '[AF]ZilartCoffer',  7,  8 },\n    [xi.job.RDM] = { '[AF]ZilartCoffer',  9, 10 },\n    [xi.job.THF] = { '[AF]ZilartCoffer', 11, 12 },\n    [xi.job.PLD] = { '[AF]ZilartCoffer', 13, 14 },\n    [xi.job.DRK] = { '[AF]ZilartCoffer', 15, 16 },\n    [xi.job.BST] = { '[AF]ZilartCoffer', 17, 18 },\n    [xi.job.BRD] = { '[AF]ZilartCoffer', 19, 20 },\n    [xi.job.RNG] = { '[AF]ZilartCoffer', 21, 22 },\n    [xi.job.SAM] = { '[AF]ZilartCoffer', 23, 24 },\n    [xi.job.NIN] = { '[AF]ZilartCoffer', 25, 26 },\n    [xi.job.DRG] = { '[AF]ZilartCoffer', 27, 28 },\n    [xi.job.SMN] = { '[AF]ZilartCoffer', 29, 30 },\n}\n\nlocal function isJobResetingEligible(player, jobId)\n    -- Check for gear table job entry existence.\n    if not jobGearTable[jobId] then\n        return false\n    end\n\n    -- Check for quest table job entry existence.\n    if not jobQuestsTable[jobId] then\n        return false\n    end\n\n    -- Check if player still has any of the job AF pieces.\n    for gearPiece = 1, #jobGearTable[jobId] do\n        if player:hasItem(jobGearTable[jobId][gearPiece]) then\n            return false\n        end\n    end\n\n    -- Check if Job has AF pieces from chest and if player has gotten them.\n    if jobCofferTable[jobId] then\n        if\n            not utils.mask.getBit(player:getCharVar(jobCofferTable[jobId][1]), jobCofferTable[jobId][2]) or\n            not utils.mask.getBit(player:getCharVar(jobCofferTable[jobId][1]), jobCofferTable[jobId][3])\n        then\n            return false\n        end\n    end\n\n    -- Check if the player has completed all job AF quests.\n    for questEntry = 1, #jobQuestsTable[jobId] do\n        if not player:hasCompletedQuest(jobQuestsTable[jobId][questEntry][1], jobQuestsTable[jobId][questEntry][2]) then\n            return false\n        end\n    end\n\n    return true\nend\n\nentity.onTrigger = function(player, npc)\n    local currentGil    = player:getGil()\n    local optionBitmask = 8388606 -- 23 bits. 1st = false. 2nd to 23th = true.\n\n    -- Build option bitmask.\n    for jobId = xi.job.WAR, xi.job.RUN do\n        if isJobResetingEligible(player, jobId) then\n            optionBitmask = optionBitmask - bit.lshift(1, jobId)\n        end\n    end\n\n    player:startEvent(10034, optionBitmask, currentGil)\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid ~= 10034 then\n        return\n    end\n\n    if option < xi.job.WAR or option > xi.job.RUN then\n        return\n    end\n\n    if not isJobResetingEligible(player, option) then\n        return\n    end\n\n    if player:getGil() < 10000 then\n        return\n    end\n\n    -- Delete gil.\n    player:delGil(10000)\n\n    -- Delete all quests.\n    for questEntry = 1, #jobQuestsTable[option] do\n        player:delQuest(jobQuestsTable[option][questEntry][1], jobQuestsTable[option][questEntry][2])\n    end\n\n    -- Delete coffer var.\n    if jobCofferTable[option] then\n        local afBitmaskName = jobCofferTable[option][1]\n        local bitOneValue   = 2 ^ jobCofferTable[option][2]\n        local bitTwoValue   = 2 ^ jobCofferTable[option][3]\n\n        player:setCharVar(afBitmaskName, player:getCharVar(afBitmaskName) - bitOneValue - bitTwoValue)\n    end\nend\n\nreturn entity\n"},["scripts/zones/Lower_Jeuno/npcs/Vola.lua"]={["Path"]="scripts/zones/Lower_Jeuno/npcs/Vola.lua",["SHA256"]="06737568f70ad1b50835cc723d20f4fc1d894a5634eac382e2eaa6a3c4532f97",["Text"]="-----------------------------------\n-- Area: Lower Jeuno\n--  NPC: Vola\n-- Starts and Finishes Quest: Fistful of Fury\n-- Involved in Quests: Beat Around the Bushin (before the quest)\n-- !pos 43 3 -45 245\n-----------------------------------\nlocal ID = zones[xi.zone.LOWER_JEUNO]\n-----------------------------------\n---@type TNpcEntity\nlocal entity = {}\n\nentity.onTrade = function(player, npc, trade)\n    if\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.FISTFUL_OF_FURY) == xi.questStatus.QUEST_ACCEPTED and\n        trade:hasItemQty(xi.item.NUE_FANG, 1) and\n        trade:hasItemQty(xi.item.MORBOLGER_VINE, 1) and\n        trade:hasItemQty(xi.item.DODO_SKIN, 1) and\n        trade:getItemCount() == 3\n    then\n        player:startEvent(213) -- Finish Quest \"Fistful of Fury\"\n    end\nend\n\nentity.onTrigger = function(player, npc)\n    local fistfulOfFury = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.FISTFUL_OF_FURY)\n    local beatAroundTheBushin = player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.BEAT_AROUND_THE_BUSHIN)\n\n    if\n        player:getFameLevel(xi.fameArea.NORG) >= 3 and\n        fistfulOfFury == xi.questStatus.QUEST_AVAILABLE and\n        player:getQuestStatus(xi.questLog.BASTOK, xi.quest.id.bastok.SILENCE_OF_THE_RAMS) == xi.questStatus.QUEST_COMPLETED\n    then\n        player:startEvent(216) -- Start Quest \"Fistful of Fury\"\n\n    elseif fistfulOfFury == xi.questStatus.QUEST_ACCEPTED then\n        player:startEvent(215) -- During Quest \"Fistful of Fury\"\n\n    elseif\n        beatAroundTheBushin == xi.questStatus.QUEST_AVAILABLE and\n        player:getMainJob() == xi.job.MNK and\n        player:getMainLvl() >= 71 and\n        player:getFameLevel(xi.fameArea.NORG) >= 6\n    then\n        player:startEvent(160) -- Start Quest \"Beat Around the Bushin\"\n\n    elseif beatAroundTheBushin ~= xi.questStatus.QUEST_AVAILABLE then\n        player:startEvent(214) -- During & After Quest \"Beat Around the Bushin\"\n\n    else\n        player:startEvent(212) -- Standard dialog\n    end\nend\n\nentity.onEventFinish = function(player, csid, option, npc)\n    if csid == 216 and option == 1 then\n        player:addQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.FISTFUL_OF_FURY)\n\n    elseif csid == 213 then\n        if player:getFreeSlotsCount() == 0 then\n            player:messageSpecial(ID.text.ITEM_CANNOT_BE_OBTAINED, xi.item.BROWN_BELT)\n        else\n            player:addTitle(xi.title.BROWN_BELT)\n            player:addItem(xi.item.BROWN_BELT)\n            player:messageSpecial(ID.text.ITEM_OBTAINED, xi.item.BROWN_BELT)\n            player:addFame(xi.fameArea.NORG, 30)\n            player:tradeComplete()\n            player:completeQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.FISTFUL_OF_FURY)\n        end\n\n    elseif\n        csid == 160 and\n        player:getQuestStatus(xi.questLog.JEUNO, xi.quest.id.jeuno.BEAT_AROUND_THE_BUSHIN) == xi.questStatus.QUEST_AVAILABLE\n    then\n        player:setCharVar('BeatAroundTheBushin', 1) -- For the next quest \"Beat around the Bushin\"\n    end\nend\n\nreturn entity\n"}};
